import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement from config
  const [posX, posY, posZ] = config.scenePosition;
  const [rotX, rotY, rotZ] = config.sceneRotation;
  const [scaleX, scaleY, scaleZ] = config.sceneScale;

  group.position.set(posX, posY, posZ);
  group.rotation.order = 'XYZ';
  group.rotation.set(rotX, rotY, rotZ);
  group.scale.set(scaleX, scaleY, scaleZ);

  // Load texture asset
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create textured plane
  const planeGeometry = new THREE.PlaneGeometry(1, 1);
  const planeMaterial = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  const plane = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(plane);

  // Create text mesh via font atlas
  const textContent = config.textContent?.[0] || 'Journal 2';
  const textMesh = ctx.fontAtlas.create({
    text: textContent,
    fontSize: 0.34,
    fontWeight: 400,
    color: config.colors.ink,
    align: 'center',
  });
  textMesh.position.z = 0.01;
  group.add(textMesh);

  // Store original Y position for hover reset
  const originalY = posY;

  // Set up interaction handlers
  group.userData.handlers = {};

  // Hover: rise-in effect (y +0.15, power3.out, 0.7s)
  group.userData.handlers.onHover = (hovering) => {
    if (hovering) {
      gsap.to(group.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    } else {
      gsap.to(group.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out',
      });
    }
  };

  // Click: emit hub-journal.select event
  group.userData.handlers.onClick = () => {
    if (ctx.emit) {
      ctx.emit('hub-journal.select');
    }
  };

  // Apply cinematic primitives from config
  if (config.cinematicPrimitives?.length) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives?.[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    });
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    // Kill all active GSAP timelines
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.rotation);
    gsap.killTweensOf(group.scale);

    // Dispose geometries
    planeGeometry.dispose();

    // Dispose materials
    planeMaterial.dispose();

    // Dispose textures
    texture.dispose();

    // Dispose text mesh resources
    if (textMesh?.geometry) textMesh.geometry.dispose();
    if (textMesh?.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach(m => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
  };

  return group;
}
